using System;
using DeadSpin.Runtime.Bootstrap;
using DeadSpin.Runtime.Interaction;
using DeadSpin.Runtime.Player;
using DeadSpin.Runtime.Presentation;
using DeadSpin.Runtime.UI;
using UnityEngine;

namespace DeadSpin.Runtime.Environment
{
    /// <summary>
    /// Assembles the complete prototype scene into the currently open scene: the casino room,
    /// the top-down table camera, GameSession, the HUD, audio and the environment director, with every reference wired. The editor menu
    /// calls this and saves the result, so the scene is generated by code instead of hand-edited YAML.
    /// </summary>
    public static class PrototypeSceneFactory
    {
        public sealed class Result
        {
            public GameSession Session;
            public Camera Camera;
            public PrototypeCasinoBuilder.Result Casino;
        }

        /// <param name="persistMaterial">Optional callback that saves generated materials as assets (editor only).</param>
        public static Result Build(Func<Material, Material> persistMaterial = null)
        {
            var materials = new PrototypeMaterials(persistMaterial);
            var result = new Result { Casino = PrototypeCasinoBuilder.Build(materials) };

            result.Camera = BuildTableCamera(result.Casino.Table);

            var sessionObject = new GameObject("GameSession");
            result.Session = sessionObject.AddComponent<GameSession>();
            sessionObject.AddComponent<GameHud>();
            sessionObject.AddComponent<AudioDirector>();
            var environment = sessionObject.AddComponent<EnvironmentDirector>();
            environment.SetTextMaterial(materials.WorldText);

            return result;
        }

        private static Camera BuildTableCamera(Transform table)
        {
            var player = new GameObject("Player");
            player.AddComponent<PlayerInputReader>();

            var cameraObject = new GameObject("TableCamera");
            cameraObject.tag = "MainCamera";
            cameraObject.transform.SetParent(player.transform, false);

            // Deactivate while wiring so Awake sees the table reference (matters when built in Play mode).
            cameraObject.SetActive(false);
            var camera = cameraObject.AddComponent<Camera>();
            camera.nearClipPlane = 0.05f;
            camera.farClipPlane = 40f;
            camera.fieldOfView = 45f;
            camera.clearFlags = CameraClearFlags.SolidColor;
            camera.backgroundColor = Color.black;
            cameraObject.AddComponent<AudioListener>();
            var rig = cameraObject.AddComponent<TableCameraRig>();
            rig.SetTable(table);
            cameraObject.AddComponent<Interactor>();
            cameraObject.SetActive(true);

            // Place the camera at the first view so the saved scene looks right in the Scene view.
            TableCameraRig.ViewPreset first = TableCameraRig.DefaultViews()[0];
            Quaternion orbit = Quaternion.Euler(first.Pitch, first.Yaw + table.eulerAngles.y, 0f);
            Vector3 focus = table.TransformPoint(first.Focus);
            cameraObject.transform.SetPositionAndRotation(focus - orbit * Vector3.forward * first.Distance, orbit);
            camera.fieldOfView = first.FieldOfView;
            return camera;
        }
    }
}
